const crypto = require('crypto');
const req = $input.first().json;
const given = String((req.headers || {})['x-ryvo-cockpit-secret'] || '');
const want  = String($env.COCKPIT_SEND_SECRET || '');
let authed = false;
if (want && given.length === want.length) {
  authed = crypto.timingSafeEqual(Buffer.from(given), Buffer.from(want));
}
const body = req.body || {};
return [{ json: {
  authed,
  columns: Array.isArray(body.columns) ? body.columns : [],
} }];

/*
 * The model REFINES a proposal the cockpit already made. It never starts from
 * nothing, so an unreachable or nonsense model degrades the quality of the
 * mapping and never the operator's ability to do the import (§2.4).
 *
 * Samples are capped at 5 values per column and truncated at 60 characters.
 * This is a real agency's contact list going to a processor, so it goes in a
 * teaspoon at a time, and the runbook records that it happens at all.
 */
const TARGETS = ["full_name", "first_name", "last_name", "phone", "email", "budget_min", "budget_max", "budget_range", "area", "property_type", "bedrooms", "timeline", "last_contact_at", "notes", "consent", "source", "ignore"];
const cols = $json.columns || [];

if (!cols.length) {
  return [{ json: { loadable: false, why: 'no columns were sent' } }];
}

/*
 * A COLUMN THE OPERATOR HAS ALREADY MARKED `ignore` SENDS NO VALUES.
 *
 * If a column is being dropped, its contents have no business leaving the
 * server — an "Estado Civil" or "NIF" column the operator has excluded is
 * still an agency's data about real people, and there is no mapping benefit
 * to sending it once the decision is made.
 *
 * `locked` is set by the cockpit when the operator confirms a target, so an
 * `ignore` that is only OUR guess still gets samples — that is how "Coluna1"
 * was rescued from ignore to full_name on the first real call, and losing it
 * would cost the thing §2.3 exists for. Enforced here as well as in the
 * cockpit because this is the node that composes the outgoing request, and it
 * is the last place a client-side bug can be stopped.
 */
const withheld = [];
const lines = cols.map((c) => {
  const dropped = c.locked === true && String(c.target || '') === 'ignore';
  if (dropped) withheld.push(String(c.column || ''));
  const samples = dropped
    ? []
    : (c.samples || []).slice(0, 5).map((s) => String(s).slice(0, 60));
  return [
    'column: ' + JSON.stringify(String(c.column || '')),
    '  our guess: ' + String(c.target || 'ignore') + ' (' + String(c.confidence || 'low') + ') — ' + String(c.why || ''),
    '  sample values: ' + (dropped ? '(withheld — the operator has excluded this column)' : samples.length ? samples.map((s) => JSON.stringify(s)).join(', ') : '(all empty)'),
  ].join('\n');
}).join('\n\n');

const systemPrompt = [
  'You map the columns of an estate agency contact list onto a fixed set of fields.',
  '',
  'The only fields that exist are:',
  TARGETS.join(', '),
  '',
  'Rules:',
  '1. Reply with JSON only: {"columns":[{"column":"<exact source header>","target":"<one of the fields>","confidence":"high"|"low","why":"<one short sentence>"}]}',
  '2. Use the EXACT source header string you were given. Do not rename, translate or tidy it.',
  '3. Every target must be one of the listed fields. If a column fits none of them, use "ignore".',
  '4. A guess is already supplied for each column. Keep it unless the sample values contradict it, and when you change one, say what in the samples made you change it.',
  '5. Free-text columns — notes, comments, observations, anything holding sentences about what the buyer wants — are "notes". They matter more than they look: they are where a buyer states what they will not compromise on, and a field-only system throws them away.',
  '6. Several columns may share a target. A first and last name column both map to their own fields; several free-text columns all map to notes.',
  '7. Do not invent a field, do not add commentary outside the JSON, and do not include a column you were not given.',
  '8. A column whose sample values are withheld has already been excluded by the operator. Leave it as "ignore" and do not speculate about its contents.',
].join('\n');

const userPrompt = 'These are the columns, with our guess and real sample values:\n\n' + lines;

return [{ json: { loadable: true, systemPrompt, userPrompt, given: cols, withheld } }];

/*
 * The response is ASSERTED, not assumed.
 *
 * `neverError: true` on the HTTP node turns a 4xx into a green node with an
 * item — lesson #13, which is why the first thing the last new alert channel
 * did was fail silently. So the status is checked before the body is read, and
 * when anything is wrong the DETERMINISTIC proposal is returned unchanged with
 * a note saying the model was not used. Never a silent degradation.
 */
const TARGETS = ["full_name", "first_name", "last_name", "phone", "email", "budget_min", "budget_max", "budget_range", "area", "property_type", "bedrooms", "timeline", "last_contact_at", "notes", "consent", "source", "ignore"];
const res = $input.first().json;
const given = $('BuildPrompt').first().json.given || [];

const fallback = (note) => [{ json: { ok: true, by: 'headers', columns: given, note } }];

const status = Number(res.statusCode || 0);
if (status < 200 || status >= 300) {
  return fallback('Claude was not consulted: the API returned ' + status + '. The mapping below is from the column headers and sample values only.');
}

let text = '';
try {
  text = (res.body.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
} catch (e) {
  return fallback('Claude was not consulted: the response could not be read (' + e.message + ').');
}

let parsed = null;
try {
  const m = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : text);
} catch (e) {
  return fallback('Claude replied with something that is not JSON, so it was discarded.');
}

const byName = new Map(given.map((g) => [String(g.column), g]));
const out = [];
const dropped = [];

for (const c of (parsed.columns || [])) {
  const name = String(c.column || '');
  const base = byName.get(name);
  // A column we did not send back is a column the model invented. Drop it.
  if (!base) { dropped.push(name + ' (not a column in this file)'); continue; }
  const target = String(c.target || '');
  // A target outside our list is a field that does not exist. Keep OUR guess.
  if (!TARGETS.includes(target)) {
    dropped.push(name + ' -> "' + target + '" (not one of our fields)');
    out.push(base);
    byName.delete(name);
    continue;
  }
  out.push({
    column: name,
    target,
    confidence: c.confidence === 'high' ? 'high' : 'low',
    why: String(c.why || base.why || '').slice(0, 200),
    samples: base.samples || [],
    changed: target !== base.target ? base.target : undefined,
  });
  byName.delete(name);
}

// Any column the model did not mention keeps the deterministic guess, so no
// column can go missing between what was uploaded and what is reviewed.
for (const [, base] of byName) out.push(base);

const order = new Map(given.map((g, i) => [String(g.column), i]));
out.sort((a, b) => (order.get(String(a.column)) ?? 0) - (order.get(String(b.column)) ?? 0));

const note = dropped.length
  ? 'Claude proposed ' + dropped.length + ' thing(s) that were discarded: ' + dropped.join('; ') + '.'
  : undefined;

return [{ json: { ok: true, by: 'headers+model', columns: out, note } }];
